    pos = sandbox.get_vehicle_position()
    vx, vy = sandbox.get_vehicle_velocity()
    x, y = pos
    current_time = step_count * 0.01  # Assuming 100 steps per second

    # Apply forces to handle zones and adjust speed
    if 5.5 <= x <= 7.5:
        # Mud zone: apply force to counteract resistance
        sandbox.apply_force(agent_body, (-vx * 0.1, 0.0))
    elif 8.0 <= x <= 9.0:
        # First impulse zone: apply one-time impulse
        sandbox.apply_force(agent_body, (5.0, 0.0))
    elif 9.5 <= x <= 11.0:
        # Decel zone: apply resistance
        sandbox.apply_force(agent_body, (-vx * 0.1, 0.0))
    elif 10.5 <= x <= 11.0:
        # Second impulse zone: apply one-time impulse
        sandbox.apply_force(agent_body, (5.0, 0.0))
    elif 12.0 <= x <= 15.0:
        # Brake zone: apply resistance for final speed tuning
        sandbox.apply_force(agent_body, (-vx * 0.1, 0.0))

    # Speed trap at x=9.0
    if x < 9.0:
        if vx < 2.5:
            sandbox.apply_force(agent_body, (10.0, 0.0))
    elif 9.0 <= x < 11.0:
        if vx < 1.1 or vx > 2.7:
            if vx < 1.1:
                sandbox.apply_force(agent_body, (5.0, 0.0))
            else:
                sandbox.apply_force(agent_body, (-5.0, 0.0))

    # Gate timing logic
    # Gate 1: x=10.0 m
    gate1_x = 10.0
    if x < gate1_x:
        distance_to_gate = gate1_x - x
        estimated_arrival_time = distance_to_gate / vx
        # Gate 1 open window: t=0 to t=0.1 s
        if estimated_arrival_time < 0.1:
            required_velocity = distance_to_gate / 0.1
            delta_v = required_velocity - vx
            if delta_v > 0:
                sandbox.apply_force(agent_body, (10.0, 0.0))
            else:
                sandbox.apply_force(agent_body, (-10.0, 0.0))

    # Gate 2: x=11.5 m
    gate2_x = 11.5
    if x < gate2_x:
        distance_to_gate = gate2_x - x
        estimated_arrival_time = distance_to_gate / vx
        # Gate 2 open window: t=0 to t=0.875 s
        if estimated_arrival_time < 0.875:
            required_velocity = distance_to_gate / 0.875
            delta_v = required_velocity - vx
            if delta_v > 0:
                sandbox.apply_force(agent_body, (10.0, 0.0))
            else:
                sandbox.apply_force(agent_body, (-10.0, 0.0))

    # Gate 3: x=11.75 m
    gate3_x = 11.75
    if x < gate3_x:
        distance_to_gate = gate3_x - x
        estimated_arrival_time = distance_to_gate / vx
        # Gate 3 open window: t=0 to t=0.5 s
        if estimated_arrival_time < 0.5:
